import test from 'node:test';import assert from 'node:assert/strict';
import {Renderer} from '../renderer.js';import {ACTOR_SHEETS} from '../actor-atlas.js';import {originalAtlas,preparedAtlasUsable} from '../atlas-fallback.js';
const images=()=>Object.fromEntries(Object.entries(ACTOR_SHEETS).map(([name,s])=>[name,{width:s.width,height:s.height,original:name}]));
function renderer(prepareAsset,compatibility=false){const rawAssets=images();return{rawAssets,assets:{...rawAssets},compatibility,prepareAsset,canvas:{dataset:{}}};}
test('a thrown or transparent processing result uses the retained original art for every actor',()=>{for(const prepare of [()=>{throw Error('readback blocked');},()=>({image:{width:1792,height:1568},bounds:Array.from({length:56},()=>({x:0,y:0,w:1,h:1}))})]){const r=renderer(prepare);Renderer.prototype.prepareSprites.call(r);for(const name of Object.keys(ACTOR_SHEETS)){assert.equal(r.assets[name],r.rawAssets[name]);assert.ok(preparedAtlasUsable({image:r.assets[name],bounds:r.bounds[name]},ACTOR_SHEETS[name].rows.length*8));}assert.deepEqual(r.fallbackAtlases,['crew','run','starter']);}});
test('compatibility mode bypasses all atlas processing and does not replace the artwork with generated placeholders',()=>{const r=renderer(()=>assert.fail('must not read pixels'),true);Renderer.prototype.prepareSprites.call(r);assert.equal(r.canvas.dataset.graphicsMode,'compatible');for(const name of Object.keys(ACTOR_SHEETS))assert.equal(r.assets[name],r.rawAssets[name]);assert.equal(r.bounds.crew.length+r.bounds.run.length+r.bounds.starter.length,128);});
test('rebuilding graphics starts from the retained Image instead of processing a prior canvas again',()=>{const seen=[],r=renderer((image,kind,cols,rows)=>{seen.push(image);const raw=originalAtlas(image,kind,cols,rows);return {...raw,image:{width:image.width,height:image.height,processed:true}};});Renderer.prototype.prepareSprites.call(r);assert.ok(r.assets.crew.processed);Renderer.prototype.prepareSprites.call(r);assert.equal(seen.length,6);assert.ok(seen.every(a=>a.original));r.compatibility=true;Renderer.prototype.prepareSprites.call(r);assert.equal(r.assets.crew,r.rawAssets.crew);});
test('one blank idle or running cell cannot leave a single animation pose invisible',()=>{const raw=originalAtlas(images().crew,'crew',8,7);raw.bounds[0]={x:0,y:0,w:1,h:1};assert.equal(preparedAtlasUsable(raw,56),false);});
